window.TEXTP["9.13"] = [{"n":268,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Также привели Ахмад, ат-Тирмизи, Ибн Маджа, Ибн Хиббан, ад-Даракутни, аль-Хаким и аль-Байхакы хадис от Бурайды, в котором сказано: <i>«Посланник Аллаха</i> (да благословит его Аллах и приветствует) <i>не выходил в день разговения, пока не поест. А в день жертвоприношения не кушал, пока не возвращался».</i> У Ахмада приводится добавка: <i>«Кушал мясо своего жертвенного животного»<sup>322</sup>.</i> В разделе имеются и другие хадисы."],["h","<b>• ВОПРОС № 8: ВРЕМЯ ПРАЗДНИЧНОЙ МОЛИТВЫ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Её время начинается после того, как солнце поднимется на высоту копья, и продолжается до того, как солнце достигнет зенита».</i>",{"mt":0.54}],["p","На это указывает хадис, который привёл Ахмад ибн аль-Хасан в «Книге жертвоприношения». В нём сказано: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>совершал намаз в День разговения тогда, когда солнце поднималось на высоту в два копья. А в День жертвоприношения — на одно копьё»<sup>323</sup>.</i>"],["p","Абу Дауд и Ибн Маджа привели хадис от ′Абду-Ллаха ибн Бусра, сподвижника посланника Аллаха (да благословит его Аллах и приветствуе, о том, что он вышел с людьми в Праздник разговения или жертвоприношения и порицал имама за его опоздание словами: <i>«В это время мы уже заканчивали…»<sup>324</sup>.</i>"],["p","Аш-Шафи′и привёл отосланную версию хадиса: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>написал ′Амру ибн Хазму, когда тот был в Наджране, письмо с приказом пораньше совершать намаз в праздник жертвоприношения и попозже в праздник разговения».</i> В цепочке передатчиков имеется Ибрахим ибн Мухаммад, шейх аш-Шафи′и, и этот хадис — слабый<sup>325</sup>."],["p","О правильности смысла этих хадисов существует единогласное мнение, даже если они и не имеют нужной степени достоверности"]],"notes":[[322,"Ахмад (5/352–360), аль-Хаким (1/264) и др."],[323,"Аль-Хафиз в «Тальхисе» (2/83) сказал: «В цепочке есть Ибн Хиляль, он обманщик»."],[324,"Абу Дауд (1135)."],[325,"Слабый, как и сказал автор комментария."]]},{"n":269,"head":"КНИГА 2. МОЛИТВА","side":"r","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["c",". Концом времени совершения намаза двух праздников является зенит солнца."],["p","В «аль-Бахр» сказано: <i>«Время их совершения — с того времени, как солнце поднялось, и до зенита. И я не знаю в этом разногласия».</i>"],["h","<b>• ВОПРОС № 9: У ПРАЗДНИЧНОЙ МОЛИТВЫ НЕТ НИ АЗАНА, НИ ИКАМЫ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«У праздичной молитвы нет ни азана, ни икамы».</i>",{"mt":0.34}],["p","На это указывает достоверный хадис от Джабира ибн Самура: <i>«Я не единожды совершал с пророком</i> (да благословит его Аллах и приветствует) <i>(праздничные намазы) без азана и икамата»<sup>326</sup>.</i>"],["p","В двух «Сахихах» имеется хадис от Ибн ′Аббаса: <i>«Не произносили азан на праздниках разговения и жертвоприношения»<sup>327</sup></i>. В разделе имеются и другие хадисы."],["p","Нет никакого сомнения в том, что в эти дни узаконено произносить такбиры. Но нет ничего, что указывало бы на какую-то конкретную их форму, время или число. Нужно просто много их произносить после намазов и в другие времена. А то, что обычно делают люди, опираясь на некоторые книги по фикху и произнося такбиры только лишь по три раза после фард-намазов и по одному разу после дополнительных— насколько я знаю, является не чем иным, как безосновательным сужением шариата."],["p","Самое достоверное, что передаётся от сподвижников — это то, что такбиры начинаются после утреннего намаза в день ′Арафата и продолжаются до последнего дня пребывания в долине Мина."],["p","Что касается словоформы такбира, то самым достоверным является то, что приводит ′Абду р-Раззак от Сальмана: <i>«Возвеличивайте Аллаха: «Аллаху акбар! Аллаху акбар! Аллаху акбару кябира!»<sup>328</sup>.</i>"]],"notes":[[326,"Ахмад (5/91), Муслим (887)."],[327,"Аль-Бухари (959)."],[328,"Я не нашёл этого предания. Возможно, оно находится в тафсире автора. Аллах знает лучше. А достоверные формы такбира можно посмотреть в сборнике Ибн Аби Шейба (2/73,74) и «аль-Ирва» (3/125,126)."]]},{"n":270,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","В «Шарху ль-Мунтака», цитируя «аль-Фатх», сказано: <i>«В наше время придумали добавки, у которых нет никакой основы».</i>"],["p","Сказал аш-Шаукани: <i>«Очевидно, что произнесение такбиров является желательным не только в конце намазов, а во все времена, как на это указывают предания».</i>"]],"notes":[]},{"n":271,"head":"КНИГА 2. МОЛИТВА","side":"r","blocks":[["h","ГЛАВА 12. МОЛИТВА СТРАХА (САЛЯТ АЛЬ-ХАУФ)",{"z":1.29}],["p","[Сказал аш-Шаукани]: <i>«Посланник Аллаха</i> (да благословит его Аллах и приветствует) <i>совершал её в различных формах».</i>"],["p","Имеются мнения о том, что этих форм шестнадцать, семнадцать, восемнадцать, а также меньше этого. Из этих форм есть достоверные, как, например, то, что он совершил с каждой группой два ракаата. Таким образом, пророк (да благословит его Аллах и приветствует) совершил четыре ракаата, а люди — два. Эта форма упомянута в двух «Сахихах» в хадисе от Джабира<sup>329</sup>."],["p","Среди этих форм также имеется та, в которой он совершил с каждой группой один ракаат. При этом у него было два ракаата, а люди совершили с ним по одному. Привёл его ан-Насаи с надежной цепочкой передатчиков<sup>330</sup>."],["p","Среди этих форм также имеется такая, в которой говорится, что он совершал намаз со всеми одновременно. Он говорил такбир, и они говорили такбир; он совершал поясной поклон, и они совершали поясной поклон; он выпрямлялся, и они выпрямлялись; он совершил земной поклон, и вместе с ним совершил земной поклон тот ряд, который стоял за ним."],["p","А последний ряд стоял напротив врага. Когда пророк (да благословит его Аллах и приветствует) заканчивал земной поклон вместе с рядом, который стоял за ним, последний ряд опускался на земной поклон. Потом ряды менялись местами и поступали так же, как в первом ракаате, однако последний ряд стал первым, а первый — последним. Затем пророк (да благословит его Аллах и приветствует) давал салям, и все вместе с ним давали салям. И эта форма упомянута в «Сахихе» Муслима в хадисе от Джабира<sup>331</sup>. Также она упомянута в хадисе от Абу Айаша, переданном Ахмадом, Абу Даудом и ан-Насаи<sup>332</sup>."],["p","Среди этих форм также присутствует такая, что он совершил один ракаат с одной группой, а другая стояла напротив врага. Затем"]],"notes":[[329,"Аль-Бухари привёл его в подвешенном состоянии (4130), а Муслим с иснадом (840)."],[330,"Ан-Насаи (3/174)."],[331,"Муслим (840)."],[332,"Ан-Насаи (3/176)."]]},{"n":272,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","эта группа ушла и встала напротив врага. Вместо них пришли другие, и пророк (да благословит его Аллах и приветствует) совершил другой ракаат, а затем дал салям. А люди завершили намаз самостоятельно. Эта форма упомянута в двух «Сахихах» от Ибн ‘Умара<sup>333</sup>."],["p","Также среди них есть такая, что с пророком (да благословит его Аллах и приветствует) встала одна группа, а другая встала спинами к кибле напротив врага. Он произнёс такбир, и все остальные произнесли его. Когда он совершил поясной поклон, его совершили и те, кто был вместе с ним. Затем, когда он совершил два земных поклона, его совершили и те, кто был вместе с ним. А другая группа так и стояла напротив врага. Потом он встал, и группа, находящаяся вместе с ним, поднялась и встала напротив врага. Вместо них пришли те, кто стоял напротив врага, и они совершили один ракаат, а пророк (да благословит его Аллах и приветствует) в это время продолжал стоять. Затем он совершил вместе с ними еще один ракаат. Затем пришла та группа, которая стояла напротив врага, а пророк (да благословит его Аллах и приветствует) и те, кто был вместе с ним, продолжали сидеть. Затем он дал салям, и все дали салям. В итоге посланник Аллаха (да благословит его Аллах и приветствует) совершил два ракаата, и все остальные совершили по два ракаата. Эту форму привели Ахмад, ан-Насаи и Абу Дауд<sup>334</sup>."],["p","Также среди этих форм есть такая, в которой он совершил один ракаат с одной группой, а другая группа стояла напротив врага. Затем он встал, и эта группа самостоятельно завершила намаз и встала напротив врага. Пришла другая группа, и он совершил вместе с ними второй ракаат, и те завершили намаз самостоятельно. Затем они вместе дали салям. Эта форма также упомянута в двух «Сахихах»<sup>335</sup>."],["p","Эти намазы во время страха отличались друг от друга по той причине, что он выбирал форму их совершения в зависимости от сложившейся ситуации, стараясь оберегать как намаз, так и людей."],["p","[Сказал аш-Шаукани]: <i>«Можно совершать любую из этих форм».</i>"]],"notes":[[333,"Аль-Бухари (4133), Муслим (839)."],[334,"Посмотри на предыдущий хадис."],[335,"Малик (1/183), аль-Бухари (4131), Муслим (841)."]]},{"n":273,"head":"КНИГА 2. МОЛИТВА","side":"r","blocks":[["p","Так как этот намаз передаётся в разных формах. То, что передаётся от пророка (да благословит его Аллах и приветствует), за тем и можно последовать. Люди делают то, что для них легче и в чём больше пользы в каждом конкретном случае. Так сказано в «Худжа»."],["p","Скажу: те учёные, которые утверждают, что узаконена только какая-то одна конкретная форма и отрицают другие формы, приведённые в достоверных хадисах, предают забвению достоверный шариат и аннулируют часть Сунны без довода! Большинство из них толкает на это их собственная нерадивость и то, что они не изучают Пречистую Сунну!"],["p","Истиной же, которую нужно принять, является то, что поступать необходимо по всем хадисам, о которых специалисты этой науки сказали, что они достоверны. Конечно же, есть формы, доводы которых не достигают должной степени достоверности."],["p","Если ты спросишь меня: «В чём же мудрость того, что пророк (да благословит его Аллах и приветствует) совершал их в разных формах?»."],["p","Я отвечу: есть две причины этого."],["p","Первая состоит в том, что ситуации бывают разными. Иногда подходит одна форма, иногда — другая. Иногда опасность сильная, иногда слабая. Иногда враг находится далеко, иногда близко. Каждый раз человек выбирает более подходящее ему."],["p","Вторая причина в том, что необходимо было объяснить людям положения шариата."],["p","Что касается магриба, то учёные единогласны в том, что он не сокращается. Разногласили учёные в том, с какой группой имаму совершить два ракаата, а с какой — один. Ничего от пророка (да благословит его Аллах и приветствует) об этом не пришло."],["p","Передаётся от ′Али, что он совершил намаз магриб в ночь Харир. Однако предания о том, какова была форма совершения того намаза, противоречат друг другу. И, как следствие, мнения учёных об этом также различны. Очевидно, что все это дозволено. Если он совершил три ракаата с одной группой, а три — с другой, то у него будет шесть ракаатов, а у людей по три. И это будет правильным, проводя аналогию с поступком пророка (да благословит его Аллах"]],"notes":[]},{"n":274,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","и приветствует). Общепринято совершать намаз имамом тому, для кого он является дополнительным, а для молящихся за ним — обязательным."],["p","[Сказал аш-Шаукани]: <i>«Если опасность усилилась и началась битва, то пеший молится на ходу, всадник молится верхом, даже если не в сторону Каабы, и даже если, только кивая».</i>"],["p","Намаз страха в момент сражения называется намазом битвы (мусаяфа). Привёл аль-Бухари от Ибн ‘Умара в толковании суры «Корова»: <b>«Если опасность усилится, то совершайте намаз на ходу или верхом, направившись в сторону киблы или без направления».</b>"],["q","Малик сказал: «Сказал Нафи′: <i>«Я не думаю, что ‘Абду-Ллах ибн ‘Умар сказал это по какой-то другой причине, кроме как той, что он услышал это от посланника Аллаха</i> (да благословит его Аллах и приветствует)<i>»<sup>336</sup>.</i> Подобное этому находится и у Муслима от Ибн ‘Умара<sup>337</sup>."],["p","Ибн Маджа передал от Ибн ‘Умара: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>описал намаз страха, сказав: <b>«Если опасность была сильнее этого, то (молитесь) на ходу или верхом»</b><sup>338</sup><b>.</b></i>"],["p","Ахмад и Абу Дауд привели с хорошим иснадом хадис от ′Абду-Ллаха ибн Унайса, в котором тот сказал: <i>«Меня отправил посланник Аллаха</i> (да благословит его Аллах и приветствует) <i>к Халиду ибн Суфьяну, когда тот был в стороне ′Урана и ′Арафата, и сказал:</i> <b><i>«Иди и убей его».</i></b> <i>Я видел его в то время, когда наступило время намаза ‘аср. Я сказал себе: «Боюсь, что по причине того, что случится между ним и мной, я не смогу совершить намаз вовремя». И я пошёл в его сторону, совершая намаз кивками. Когда я приблизился к нему…»<sup>339</sup>.</i> Было бы странным, если бы он не упомянул об этом пророку (да благословит его Аллах и приветствует)."]],"notes":[[336,"Аль-Бухари (943)."],[337,"Муслим (839)."],[338,"Ибн Маджа (1258)."],[339,"Слабый. «Да’иф Абу Дауд» (271)."]]},{"n":275,"head":"КНИГА 2. МОЛИТВА","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","ГЛАВА 13. МОЛИТВА В ПУТИ",{"z":1.29}],["h","<b>• ВОПРОС № 1: ОБЯЗАТЕЛЬНОСТЬ СОКРАЩЕНИЯ МОЛИТВ В ПУТИ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Обязательно сокращать молитвы…».</i>",{"mt":0.54}],["p","На это указывает хадис от ′Айши, находящийся в «Сахихе», в котором сказано: <i>«Пророк</i> (да благословит его Аллах и приветствует), <i>сказал: <b>«Вначале было предписано совершать намаз из двух ракаатов. Затем такой намаз был предписан только путешественникам, а намаз тех, кто находился в постоянном месте проживания, был дополнен»</b><sup>340</sup><b>.</b></i>"],["p","Смысл данного хадиса даёт чувство того, что намаз путника остался на своей основе, и если кто-то совершит намаз в пути, не сокращая, то это подобно тому, что он, находясь дома, намеренно совершил восемь ракаатов вместо четырёх. Также достоверно известно, что пророк (да благословит его Аллах и приветствует), сказал: <i><b>«Это милостыня, которую подаёт вам Аллах. Так примите же эту милостыню!»</b><sup>341</sup><b>.</b></i>"],["p","Пророк (да благословит его Аллах и приветствует) во всех своих путешествиях ограничивался сокращением намаза."],["p","Я уже говорил: община единогласна в том, что разрешено сокращать намазы в путешествии. Но толкователи Корана имели разные мнения относительно тафсира слов Всевышнего: <b>«Когда вы странствуете по земле, то нет на вас греха, если вы сократите некоторые из намазов, если вы опасаетесь искушения со стороны неверующих…»</b><sup>342</sup><b>.</b>"],["p","Они ниспосланы по поводу путешествия, а условие страха пришло вместе с ним; или они ниспосланы относительно страха, а условие путешествия пришло вместе с ним? И под словом «сокращение» (каср) имеются в виду кивки во время поясного и земного поклона."]],"notes":[[340,"Аль-Бухари (1090), Муслим (685) и другие. Шейх аль-Альбани сказал: «Это является словами ‘Айши. Но хукм его восходящий, в чём нет сомнения. Однако это говорил не посланник Аллаха (да благословит его Аллах и приветствует)»."],[341,"Муслим (686) и другие."],[342,"Сура «ан-Ниса», аят 101."]]},{"n":276,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","Первого мнения придерживается группа толкователей. На второе указывают слова Ибн ′Умара, а также то, что за этим аятом следуют слова Аллаха: <b>«Когда ты находишься среди них…»</b><sup>343</sup><b>.</b>"],["p","Мнением большинства учёных является то, что сокращение — обязательно. А имам аш-Шафи′и сказал: <i>«Если захочет, то пусть совершит его полностью, а захочет — пусть сократит, и это будет лучше».</i> Так сказано в «аль-Мусаува»."],["p","Скажу: истиной же является обязательство сокращать. На это указывают ясные хадисы. А что касается того, что передаётся от ′Айши: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>сокращал намаз и совершал его полностью, постился и разговлялся»<sup>344</sup>,</i> — то этот хадис недостоверный, как об этом ясно сказала группа знатоков хадиса (хуффаз)<sup>345</sup>. А о том предании, в котором сказано, что она совершала намаз в пути полностью и пророк (да благословит его Аллах и приветствует) не порицал её за это, есть критика со стороны группы имамов, по причине которой оно теряет силу довода<sup>346</sup>."],["p","Передаваемое от ′Усмана сообщение о том, что он совершил намаз в Мине, не сокращая его, не является доводом, так как некоторые сподвижники порицали его и он оправдывался. В этом вопросе не осталось ничего такого, что заставляло бы колебаться."]],"notes":[[343,"Здесь мы видим, что для понимания книг такого уровня человек должен обладать большим количеством информации. Например, для того чтобы понять данное место, человеку нужно знать, что сказал Ибн ′Умар о сокращении намаза, а также знать когда, как и по какому поводу были ниспосланы эти аяты. Что бы там ни было, это большой труд. Эти знания даются только через большое старание и напряжение разума."],[344,"Ад-Даракутни (2/189), аль-Хафиз в «Булюгу ль-Марам» сказал: «Хадис ′Ата от ′Айши имеет «болезни». А то, что передаётся достоверно от ‘Айши, относится к её поступку: «Он не порицал меня». Это предание привёл аль-Байхакы». Ахмад посчитал это предание порицаемым. См. «Субулю с-Салям» (2/77), «аль-Ирва» (3/6–7)."],[345,"Ахмад Шакир сказал: <i>«Тому, кто посмотрел на цепочку передатчиков этого хадиса, ничего не останется, кроме как признать его хорошим и имеющим силу довода, если не достоверным».</i> См. «Найлю ль-Аутар» часть 3, стр. 248–"],[250,""],[346,"Посмотри слова Ибн аль-Кайима в «аз-Зад» (1/472–473). Поистине, они важные, «аль-Ирва» (3/7–8)."]]},{"n":277,"head":"КНИГА 2. МОЛИТВА","side":"r","blocks":[["p","Явный смысл хадисов указывает на то, что сокращать намаз и разговляться может любой путник, неважно, находится он на пути Аллаха или пребывает в ослушании<sup>347</sup>."],["p","Ведь Аллах узаконил сокращение намаза для путника так же, как и узаконил совершение его полностью для местного жителя. При этом нет разницы в том, ослушается ли местный житель Аллаха или послушается ему — он совершает намаз по четыре ракаата."],["p","Сокращать намаз в пути является проявлением решительности (азима) и основой. То есть совершение в пути двух ракаатов вместо четырёх является даже не сокращением. Это и есть полное его совершение в пути! Поэтому мы не можем сказать ослушавшемуся не поступать так. А разговение в пути является разрешением и послаблением (рухса). Поэтому в основе мы могли бы допустить, что оно относится к подчиняющемуся и не относится к ослушавшемуся. Но это неправильно, так как доводы не разделяют между ослушавшимся и подчиняющимся даже в отношении разговения в пути. Мы хотим сказать, что нельзя сравнивать разрешение путнику разговляться с сокращением в пути намаза и эта аналогия (кыяс) неправильна!"],["p","Проявлением этого вопроса в практическом фикхе является следующее:"],["p","В ханафитском мазхабе фард-намаз путника не может быть больше двух ракаатов (кроме магриба)."],["p","А если кто-то совершил его в четыре ракаата и при этом не садился на срединный ташаххуд, то его намаз недействительный. Если же садился, то последние два будут считаться дополнительными ракаатами. В шафиитском мазхабе человек не должен восполнять то, что он сократил в пути, если его путешествие закончилось. В отличие от поста: он должен восполнить те дни, в которые он разговлялся."]],"notes":[[347,"Некоторые учёные сказали, что если человек вышел в путешествие, в котором он пребывает в ослушании Аллаха, то ему нельзя сокращать или разговляться, как, например, человек, вышедший грабить караваны."]]},{"n":278,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":46.9,"mt":0,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","<b>• ВОПРОС № 2: О ТОМ, В КАКОМ ПУТИ РАЗРЕШЕНО СОКРАЩАТЬ МОЛИТВЫ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Это касается того, кто покинул свой город, отправившись в путь, даже если его расстояние меньше одного барида (12 миль)».</i>",{"mt":0.34}],["p","Это извлекается из слов Всевышнего Аллаха: <b>«Когда вы странствуете по земле, то нет на вас греха, если вы сократите намаз»</b><sup>348</sup><b>.</b>"],["p","Слово <b>«странствуете»</b> (дарабтум) можно отнести к любому путешествию, без определения расстояния. К нему не относится выход человека без намерения путешествовать, как, например, выход посланника Аллаха (да благословит его Аллах и приветствует) на кладбище аль-бакы′ и подобное этому."],["p","В этом случае человек не сокращает намаз. В шариате не имеется ничего, что определяло бы расстояние путешествия. В этом случае становится обязательным обращение к языковому смыслу этого слова. Если человек вышел из своего города с намерение добраться до какого-либо места, где он считается путником, то он сокращает намаз. Даже если это расстояние находится ближе одного барида (12 миль). Нет в шариате чего-то, что обязывало бы брать в расчёт расстояние барида, день пути, два, три или больше этого. Единственное, что приводят в отношении этого, так это хадис: <b><i>«Не разрешается женщине, которая уверовала в Аллаха и в Судный День, путешествовать на расстояние трёх дней пути без махрама».</i></b>"],["p","В другой версии: <i><b>«…дня и ночи».</b></i> В третьей версии: <i><b>«…на расстояние барида»</b><sup>349</sup></i>. Но ни в хадисе, ни в его контексте ничего не упоминается о сокращении намаза и приведение этого хадиса в качестве довода является не чем иным, как простыми догадками."],["p","Лучшим, чем это, в определении расстояния пути является то, что привёл Шу’ба от Яхьи ибн Зайда, в котором тот сказал: <i>«Я спросил Анаса о сокращении намаза, и он ответил: «Посланник Аллаха</i> (да благословит его Аллах и приветствует) <i>если выходил в путь на расстояние больше трёх милей или трех фарсахов (это 9 миль), сокращал намаз».</i> Сомнение, имеющееся в этом предании, принадлежит Шу’бе."]],"notes":[[348,"Сура «ан-Ниса», аят 101."],[349,"Шейх аль-Альбани сказал, что эта добавка слабая (шазз)."]]},{"n":279,"head":"КНИГА 2. МОЛИТВА","side":"r","blocks":[["c","Это предание привёл Муслим и другие<sup>350</sup>."],["p","Если ты мне скажешь, что путешествием называется то расстояние, на которое запрещено отправляться женщине без махрама, то я отвечу: тот факт, что в хадисе это расстояние названо путешествием, не противоречит тому, чтобы назвать путешествием передвижение и на гораздо меньшее расстояние. Ведь пророк (да благословит его Аллах и приветствует) назвал путешествием передвижение на расстояние трёх дней пути и на расстояние одного барида, и это мы говорим, основываясь на разные версии передачи этого хадиса. Но именование путешествием передвижения на расстояние одного барида также не противоречит тому, чтобы назвать путешествием передвижение и на меньшее расстояние."],["p","Если ты скажешь, что, мол, ат-Табарани, аль-Байхакы и ад-Даракутни привели хадис от Ибн ′Аббаса, в котором сказано: <i>«Сказал посланник Аллаха</i> (да благословит его Аллах и приветствует)<i>:</i> <b><i>«О жители Мекки! Не сокращайте намаз при путешествии на расстояние менее четырёх баридов из Мекки до ′Усфана»,</i></b> — то я скажу, что этот хадис слабый и не может являться доводом. В цепочке его передатчиков есть ‘Абду ль-Ваххаб ибн Муджахид, а он — оставленный передатчик<sup>351</sup>."],["p","Автор сказал: <i>«В этом вопросе много мазхабов. И, на мой взгляд, упомянутый мазхаб является самым сильным».</i>"],["p","Абу Ханифа сказал: <i>«Путешествием является передвижение на расстояние трёх дней пути».</i>"],["p","В «аль-‘Алямкирийя» сказано: <i>«Правильным является то, что передвижение на расстояние целого дня и ночи пути — не является условием путешествия. Если человек вышел утром, шёл до обеда, а потом остановился, то он считается путником».</i>"],["p","Аш-Шафи′и сказал: <i>«Четыре барида».</i>"],["p","Малик сказал: <i>«Это то, что мне более всего нравится из того, что я слышал о сокращении намаза в путешествии. Речь идёт о шестнадцати фарсахах».</i>"]],"notes":[[350,"Муслим (691)."],[351,"Ад-Даракутни (1/387). Слабым его назвали аль-Байхакы и аль-Хафиз в «Тальхисе»."]]},{"n":280,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","Аль-Ауза′и сказал: <i>«Абсолютное большинство факыхов считают, что путешествием называется передвижение на расстояние целого дня пути. Разрешается начать сокращение намаза с того момента, как он покинул строения города».</i>"],["p","Скажу: в вопросе определения самого маленького расстояния, которое считается путешествием, имеются многочисленные мнения, и споры не прекращаются с давних пор. И нет ничего, на что можно было бы опереться, кроме рассказов передатчиков о том, на каком расстоянии сокращал пророк (да благословит его Аллах и приветствует) свой намаз. Они не разъясняли, на каком расстоянии заканчивалось его путешествие. Самое ясное из того, что сказали некоторые передатчики— это то, что он сокращал свой намаз на расстоянии трёх миль или трех фарсахов, сомневаясь в точном определении этого расстояния. Некоторые опирались на хадис: <b><i>«Не дозволено женщине…».</i></b> Однако нет взаимосвязи между обязательством присутствия махрама для путешествующей женщины и обязательством сокращения намаза! Ведь причины узаконенности у них разные! Из этого следует, что ничего не остаётся из того, на что можно было бы опереться в определении сущности путешествия, кроме того, что действия путника в его перемещениях относительно своего жилища должны отличаться от действий местного жителя. А перемещение человека возле своего дома на расстояние одной мили ну никак не назовешь путешествием. Пророк (да благословит его Аллах и приветствует) выходил на кладбище аль-Бакы′ для того, чтобы навещать мёртвых, и не сокращал намаз. Это можно было бы взять как довод, если бы там наступило время намаза и он совершил бы его, не сокращая, но этого не передаётся. Сказать, что самым маленьким расстоянием является одна миля, тоже трудно. Наша цель — не уходить от основ и отдалиться от произвола, подобного тому, что сказали некоторые учёные, якобы путешествие — это преодолевание расстояния между Ираком и Шамом."],["p","Резюмируя, скажу: в вопросе определения того, что же такое путешествие, мы должны брать во внимание языковое понимание и то, что обычно считается таковым у людей."],["p","А предание, передаваемое от Са′ида ибн Мансура, о том, что он сказал: <i>«Когда он путешествовал на расстояние одного фарсаха, то сокращал</i>"]],"notes":[]},{"n":281,"head":"КНИГА 2. МОЛИТВА","side":"r","blocks":[["c","<i>намаз»<sup>352</sup>,</i> — оно также не отрицает того, что путешествием может считаться и перемещение на гораздо меньшее расстояние, чем один фарсах."],["p","[Сказал аш-Шаукани]: <i>«Если путник останавливается где-то на неопределенный срок, то сокращает до двадцати дней».</i>"],["p","А затем совершает их полностью, ведь если человек снял седло, остановившись в каком-либо доме, то он уже не путешествует и его оставили трудности пути."],["p","И если бы пророк (да благословит его Аллах и приветствует) не назвал такого человека путником, сказав: <b><i>«О, жители Мекки! Совершайте намаз полностью! А мы являемся путниками!»</i></b> — то с него бы снялся хукм путника. Поэтому в сокращении намаза нужно ограничиться тем временем, на которое разрешил сокращать Законодатель. А если отрезок времени пребывания в какой-то местности превышает узаконенное количество дней, то с него снимается хукм путешественника, и он обязан совершать намазы полностью, так как он становится местным жителем. Было сказано, что пророк (да благословит его Аллах и приветствует) пребывал в Мекке во время её взятия, сокращая намаз восемнадцать ночей, также было сказано о девятнадцати ночах, а также о меньшем сроке. В «Сахихе» аль-Бухари было сказано о девятнадцати ночах<sup>353</sup>."],["p","Привели Ахмад и Абу Дауд хадис от Джабира, в котором тот сказал: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>пробыл в Табуке двадцать ночей, сокращая при этом намаз»<sup>354</sup></i>. Этот же хадис привели Ибн Хиббан, аль-Байхакы и Ибн Хазм, назвавший его достоверным. А также достоверным его назвал ан-Навави. Нам тоже нужно ограничиться этим отрезком времени, а после этого совершать намаз полностью."],["p","Как же прекрасно понимание Ибн ′Аббаса! Как же хорошо он знает цели шариата! Он сказал в том, что передал аль-Бухари и другие: <i>«Когда пророк</i> (да благословит его Аллах и приветствует) <i>взял Мекку,</i>"]],"notes":[[352,"Также это предание передаёт Ибн Аби Шейба (2/442). В его цепочке имеются Абу Харун, хадисы которого неприемлемы, и Хушайм, который подтасовывал иснады."],[353,"Аль-Бухари, Абу Дауд (1230)."],[354,"Абу Дауд (1236)."]]},{"n":282,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","<i>он жил там девятнадцать дней, совершая намаз по два ракаата. И мы тоже, если остановимся где-то на девятнадцать дней, сократим намаз, а если на больший срок — то совершим его полностью»<sup>355</sup>.</i>"],["p","Скажу: вот это и есть точный фикх! Это — мнение, основанное на совершенном исследовании!"],["p","Автор сказал: <i>«В этом вопросе много мазхабов, и этот, на мой взгляд, наиболее сильный».</i>"],["p","Скажу: очевидным является тот факт, что если человек остановился в каком-то городе и живёт там день за днём, то он не является путником и совершает намаз полностью<sup>356</sup>. Если бы не было довода, указывающего на то, что человек, временно остановившийся где-то и твердо решивший, что он уедет, является путником, — хукм путника снялся бы с него. И мы должны ограничиться тем периодом, на который указывает довод."],["p","А если человек не решил, когда он уедет, то он должен сокращать намаз столько, сколько сокращал его посланник Аллаха (да благословит его Аллах и приветствует), находясь в Мекке. То есть самое большее — это двадцать дней<sup>357</sup>. Также передаётся, что он пребывал в битве при Табуке в одном месте примерно столько же времени."],["p","Кто-то может сказать, что это просто действие пророка (да благословит его Аллах и приветствует), и мы не можем опираться на него и не можем запретить сокращать намаз в течение большего срока, чем этот период времени. Откуда нам знать, сокращал бы он намаз или совершал бы полностью, остановись он на более длинный срок? Да, это правильное суждение. Но мы не говорим, что только это действие является доводом. Мы говорим, что тот, кто остановился где-то на срок, превышающий то время, на которое обычно останавливаются путники для того, чтобы отдохнуть и дать отдых своим животным, а это день, полдня или сутки, тот в основе своей перестаёт быть путником. И неправильно будет его называть путником. Поэтому обязательно ограничиться тем временем, в течение которого пророк (да благословит его Аллах и приветствует), остановившись, сокращал намаз и сказал: <b><i>«Мы являемся путниками</i></b>"]],"notes":[[355,"Аль-Бухари (1080)."],[356,"Шейх хочет сказать, что это и есть основа."],[357,"См. «аль-Ирва» (3/25–26)."]]},{"n":283,"head":"КНИГА 2. МОЛИТВА","side":"r","blocks":[["c","<b><i>».</i></b> А тот, кто утверждает, что можно сокращать намаз больше этого времени, тот обязан привести довод."],["p","В отношении же хукма того человека, который твёрдо знает на сколько он остановился, имеются разногласия. Некоторые сказали, что это четыре дня. А в качестве довода привели то, что пророк (да благословит его Аллах и приветствует) останавливался в прощальном хадже на четыре дня и сокращал намаз."],["p","Методология приведения довода точь-в-точь такая же, как и в отношении того, кто не знает, на сколько дней он остановился. Это самое лучшее из того, что было сказано."],["p","Последователи других мнений опираются на различные иджтихады сподвижников, которые не являются доводом. На мнение об ограничении обязательства сокращения намаза четырьмя днями можно возразить, даже если оно и является самым сильным из того, что было сказано! Можно сказать, откуда нам знать, что пророк (да благословит его Аллах и приветствует) твёрдо решил остановиться на эти четыре дня? Нам ведь этого никто не передал! На это возражение можно ответить следующим образом: обряды хаджа невозможно выполнить в более короткий срок. Это указывает на наличие твёрдого решения поступить так."],["p","А что касается того, что передаётся от Анаса о том, что он сказал: <i>«Мы пробыли с пророком</i> (да благословит его Аллах и приветствует) <i>десять дней»<sup>358</sup>,</i> — то это относится ко всем дням пребывания в Мекке и возле неё. А срок пребывания в самой Мекке не превышал четырёх дней. Пусть знают это."],["p","[Сказал аш-Шаукани]: <i>«А если он решил остановиться на четыре дня, то по их истечении совершает намаз, не сокращая его».</i>"],["p","Ведь мы знаем, что на местного жителя не распространяются положения путника. Нужно ограничиваться тем сроком, на который указал Законодатель. Мы уже разобрали вопрос о том путнике, который не решил, на сколько дней он остановился в какой-либо местности. Тот, кто остановился на какое-то конкретное время, также должен сокращать намаз столько времени, сколько сокращал его пророк (да благословит его Аллах и приветствует) в таком случае. Достоверно известно, что он прибыл в Мекку утром четвёртого"]],"notes":[[358,"Аль-Бухари (1081), Муслим (793)."]]},{"n":284,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","Зуль-Хиджа. Утром восьмого числа, совершив утренний намаз, он выехал из Мекки. Итого он пробыл в Мекке, сокращая намаз, четыре дня. Это и является доводом, указывающим на то, сколько времени должен сокращать намаз путник, остановившийся на конкретное количество дней. Мы не говорим, что если бы пророк (да благословит его Аллах и приветствует) пробыл там больше четырёх дней, то не стал бы сокращать. Мы этого не знаем и не можем утверждать. Мы это говорим, так как путешественник, остановившийся на какое-то определённое количество дней, не может сокращать намаз, кроме как с разрешения шариата. То же самое касается и колеблющегося в выборе срока своего пребывания, как мы упомянули об этом выше. Но нет ничего в шариате, что дозволило бы сокращать намаз большее количество дней, и ничего, кроме упомянутого здесь, не известно."],["p","Сказал аш-Шафи′и: <i>«Если путник решил остановиться где-либо на четыре дня, его путешествие прерывается с момента прибытия на это место».</i>"],["p","В «аль-Минхадж» сказано: <i>«Более правильным мнением является то, что день прибытия и отъезда не входят в число дней пребывания».</i>"],["p","Абу Ханифа сказал: <i>«Путник не перестаёт считаться путником, пока не решил остаться где-либо на срок более пятнадцати дней».</i>"],["p","Большинство же учёных считают, что он сокращает намаз до тех пор, пока не решит поселиться в этой местности. Последователи аш-Шафи′и разногласят в передаче его мнения по этому поводу. Аль-Багави передаёт, что если путник не намерен поселиться в этой местности, но его пребывание в ней продлится более четырёх дней, то он не сокращает намазы. Это не касается случаев, когда там идёт вой на или есть какая-то опасность. В таких случаях он сокращает намаз. Пророк (да благословит его Аллах и приветствует) сокращал намаз в год взятия Мекки во время битвы Хавазин девятнадцать или восемнадцать дней. Есть у него и другое мнение, которое совпадает с мнением большинства."],["p","Автор сказал: <i>«Знай, что эти три упомянутых исследования относятся к тем войнам, от которых притупляется разум. Мазхабы в этом вопросе сильно отличаются друг от друга, а взгляды людей излишне противоречивы».</i>"]],"notes":[]},{"n":285,"head":"КНИГА 2. МОЛИТВА","side":"r","blocks":[["p","[Сказал аш-Шаукани]: <i>«Он может объединять два намаза, совершая их в любое из двух их времён».</i>"],["p","На это указывает хадис от Анаса, находящийся в двух «Сахихах», в котором сказано: <i>«Если пророк</i> (да благословит его Аллах и приветствует) <i>выезжал до зенита, то откладывал зухр до времени ‘аср, а потом, останавливаясь в каком-либо месте, совершал его вместе с ‘асром. А если он выезжал после зенита, то совершал зухр, а потом трогался в путь»<sup>359</sup>.</i>"],["p","Привели Ахмад, ат-Тирмизи, Ибн Маджа, аль-Хаким и ад-Даракутни, а ат-Тирмизи назвал его хорошим, хадис от Муаза: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>в походе на Табук, если отправлялся в путь до зенита солнца, то откладывал зухр, совершая его вместе с ‘аср. А если он отправлялся после зенита солнца, то совершал зухр, совмещая его с ‘асром, и затем трогался в путь»<sup>360</sup></i>. Ахмад привёл подобный хадис от Ибн ′Аббаса с добавкой о магриб и ‘иша намазах<sup>361</sup>. Аль-Байхакы и ад-Даракутни привели хадис, цепочку которого Ибн аль-′Араби назвал достоверной. Однако позднее к его словам было добавлено, что в цепочке есть передатчик, хадисы которого не принимаются. У этих двух хадисов есть пути, поддерживающие друг друга по различным путям передачи. Из той критики, которая сказана в адрес этих хадисов, нет ничего, что лишило бы их статуса доказательства."],["p","А также в двух «Сахихах» приведён хадис от Ибн ′Умара о совмещении магриба и ‘иша: <i>«Пророк</i> (да благословит его Аллах и приветствует) <i>во время пути откладывал совершение магриба до тех пор, пока не исчезало красное зарево заката. А затем он совмещал его вместе с ‘иша»<sup>362</sup>.</i>"],["p","Сказал Ибн аль-Кайим: <i>«У этой Сунны высшая степень достоверности и ясности, и нет ничего, что бы противоречило ей. Опровергнута она была тем, что якобы это хадисы — ахад, а времена намаза установлены хадисами мутаватир, подобными хадисам об имамстве Джибриля для пророка</i> (да благословит его Аллах и приветствует) <i>и его ответу</i>"]],"notes":[[359,"Аль-Бухари (1111), Муслим (804)."],[360,"Ахмад (5/241–242)."],[361,"Аш-Шафи′и (1/116). Этот хадис слабый, однако он достигает степени достоверного по причине поддерживающих его версий."],[362,"Аль-Бухари (1109), Муслим (703)."]]},{"n":286,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["c","<i>на вопрос о временах намаза. Эти хадисы однозначные, достоверные и ясные, и в них содержится подробное описание времён намаза. Община имеет единогласное мнение о приемлемости этих хадисов. А хадисы, в которых описывается совмещение намазов, не до такой степени ясные, чтобы, опираясь на них, можно было бы разрешить совмещение намазов действием и во времени<sup>363</sup>. Как можно оставить подробно объяснённые доводы, опираясь на обобщённые?!</i>"],["p","В ответ на всё это можно сказать: совмещение намазов является истиной! И тот, кто научил нас временам намаза и объяснил их своими словами и действиями, он же и узаконил для нас совмещение намазов, объяснив это своими словами и действиями. Ни в коем случае нельзя брать часть Сунны, оставляя при этом другую! Хадисы, в которых сказано о совмещении намазов, по отношению к хадисам о совершении их по отдельности, подобны отношению хадисов, в которых сказано об облегчениях, связанных с трудностями, к хадисам, в которых разъяснены условия и обязательства намаза! Некоторая часть Сунны разъясняет остальную её часть, и ни в коем случае одна не опровергает другую!"],["p","<i>Внимательно изучивший хадисы о совмещении намазов обнаружит, что все они ясно говорят о дозволенности совмещения в любое из времён двух совмещаемых намазов, а не только о дозволенности лишь фиктивного совмещения…».</i> Так сказано в «И′ляму ль-Муваккы′ин»."],["p","В «аль-Мусаува» сказано: <i>«Большинство учёных дозволяют совмещение зухра с ‘асром и магриба с ‘иша в одно из двух времён каждой пары этих намазов. Как я уже сказал, ханафиты не разрешают этого. А хадисы о совмещении намазов они толкуют таким образом: один намаз откладывается до конца его времени, а другой совершается в начале своего времени, и таким образом происходит их фиктивное совмещение. Они передают это от ′Али и Са′да ибн Аби Ваккаса. А что касается совмещения намазов по нужде, то о дозволенности этого существует единогласное мнение».</i>"]],"notes":[[363,"Совмещение действием факыхи называют «фиктивным объединением намазов», когда, например, зухр совершается в самом конце его времени, а ‘аср — в самом начале своего времени. А совмещением во времени именуется совершение двух намазов подряд в одно из их времён, например, зухр и ‘аср во время зухра."]]},{"n":287,"head":"КНИГА 2. МОЛИТВА","side":"r","blocks":[["p","[Сказал аш-Шаукани]: <i>«С одним азаном и двумя икамами».</i>"],["p","Так как на это указывает хадис, находящийся в двух «Сахихах», о совмещении намазов в долине Муздалифа<sup>364</sup>."]],"notes":[[364,"Аль-Бухари, ан-Насаи от Ибн ′Умара. Муслим, ан-Насаи и Ахмад от Джабира."]]}];
